/**
 * Time left until a moment, ticking each second (`design/components/countdown.md`).
 *
 * Generated by `pnpm shells` from `packages/shells/src/members/countdown.ts`, the member's
 * framework-neutral description. Never edit it by hand: change the description and
 * run `pnpm shells`.
 */
import { createMemo, mergeProps, onCleanup, type JSX } from 'solid-js'

import {
  claimSlot,
  countdownClock,
  countdownLeft,
  countdownMoment,
  countdownSpoken,
  createCell,
  createDerived,
  devWarning,
  followCountdown,
  watchEffect,
  type Defaults,
} from '@polymorph/solid'
import styles from '@polymorph/recipes/structure/countdown.module.css'

export interface CountdownMessages {
  mark: (label: string, time: string) => string
}

export interface CountdownProps {
  /**
   * Says the time left in a polite line at one minute and at ten seconds. Off, nothing is said.
   */
  announce?: boolean
  /**
   * What it counts to, for assistive technology: "Time until you can send a new code".
   */
  label: string
  /**
   * The locale `Intl` writes the digits and the words in; the page's own when absent.
   */
  locale?: string
  /**
   * Omit for the generic English defaults; localized hosts pass their own.
   */
  messages?: CountdownMessages
  /**
   * Called once when the moment is reached, and once after mount when it has already passed.
   */
  onEnd?: () => void
  /**
   * The moment it counts to: an ISO-8601 instant, as RelativeTime reads its value. Not a number
   * of seconds, which would start again on every render. A server's "retry after 30" becomes a
   * moment once, where the app receives it.
   */
  until: string
}

/** Time left until a moment, ticking each second. */
export default function Countdown(given: CountdownProps): JSX.Element {
  const props = mergeProps(
    { announce: false } as Defaults<CountdownProps, 'announce'>,
    claimSlot(given),
  )
  const reading = createCell(null as { at: number; left: number } | null)
  const said = createCell(null as { at: number; text: string } | null)
  const ended = createCell(null as number | null)
  const moment = createDerived(() => countdownMoment(props.until))
  const say = createDerived(
    () => props.messages ?? { mark: (label: string, time: string) => label + ': ' + time },
  )
  const time = createDerived(() => ({
    left:
      reading.value !== null && reading.value.at === moment.value
        ? reading.value.left
        : moment.value === null
          ? 0
          : countdownLeft(moment.value),
  }))
  const heard = createDerived(() =>
    said.value !== null && said.value.at === moment.value ? said.value.text : '',
  )
  const heed = createDerived(() => (at: number) => (left: number, marked: boolean): void => {
    reading.value = { at: at, left: left }
    if (marked && props.announce)
      said.value = {
        at: at,
        text: say.value.mark(props.label, countdownSpoken(left, props.locale)),
      }
    if (left === 0 && ended.value !== at) {
      ended.value = at
      props.onEnd?.()
    }
  })
  let release1: (() => void) | undefined
  const effect1 = () => {
    release1?.()
    const ran =
      moment.value === null ? undefined : followCountdown(moment.value, heed.value(moment.value))
    release1 = () => {
      ran?.()
    }
  }
  watchEffect(
    createMemo(() => moment.value),
    effect1,
    true,
  )
  onCleanup(() => release1?.())
  const effect2 = () => {
    devWarning(
      moment.value === null,
      `Countdown could not read "${props.until}" as a moment — rendering nothing.`,
    )
  }
  watchEffect(
    createMemo(() => moment.value),
    effect2,
    true,
  )
  return (
    <>
      {moment.value !== null ? (
        <span
          class={styles.countdown}
          data-ended={time.value.left === 0 ? '' : undefined}
          data-allow-mismatch="attribute"
          data-member="countdown"
        >
          <time
            role="timer"
            aria-label={props.label}
            datetime={'PT' + time.value.left + 'S'}
            data-allow-mismatch="text,attribute"
          >
            <span class={styles.digits} aria-hidden="true">
              {countdownClock(time.value.left, props.locale)}
            </span>
            <span class={styles.spoken}>{countdownSpoken(time.value.left, props.locale)}</span>
          </time>
          {props.announce ? (
            <span class={styles.spoken} role="status">
              {heard.value}
            </span>
          ) : null}
        </span>
      ) : null}
    </>
  )
}
